/**
 * Express Controllers Template Generator for mern-integrations CLI
 */

export function generatePaymentController(options = {}) {
  const payments = Array.isArray(options.payments) ? options.payments : [];
  const primary = payments[0] || 'phonepe';

  return `/**
 * Payment Controller
 * Auto-generated by: npx mern-integrations init
 */

import { ${primary} } from '../config.js';
import { ValidationError, IntegrationError } from 'mern-integrations';

/**
 * Creates a payment order / initiates payment.
 * Amount must be specified in the smallest currency unit (e.g. paise / cents).
 */
export async function createOrder(req, res) {
  try {
    const { amount, currency = 'INR', customerId, notes } = req.body;

    const order = await ${primary}.createOrder({
      amount: Number(amount),
      currency,
      receipt: \`rcpt_\${Date.now()}\`,
      customerId,
      notes
    });

    res.status(201).json(order);
  } catch (error) {
    handleError(res, error);
  }
}

/**
 * Verifies payment server-to-server or validates callback signature.
 */
export async function verifyPayment(req, res) {
  try {
    const payload = req.body;
    let result;

    if (typeof ${primary}.verifyPayment === 'function') {
      result = await ${primary}.verifyPayment(payload);
    } else if (typeof ${primary}.verifySignature === 'function') {
      result = ${primary}.verifySignature(payload);
    } else {
      return res.status(400).json({ error: 'Verification method not supported by provider' });
    }

    res.status(200).json(result);
  } catch (error) {
    handleError(res, error);
  }
}

/**
 * Initiates a payment refund.
 */
export async function refundPayment(req, res) {
  try {
    const { paymentId, amount, reason } = req.body;

    if (!${primary}.capabilities.includes('refund')) {
      return res.status(400).json({ error: 'Refunds not supported by this provider' });
    }

    const refundResult = await ${primary}.refund({
      paymentId,
      amount: Number(amount),
      reason
    });

    res.status(200).json(refundResult);
  } catch (error) {
    handleError(res, error);
  }
}

function handleError(res, error) {
  if (error instanceof ValidationError) {
    return res.status(400).json({ error: error.message, details: error.details });
  }
  if (error instanceof IntegrationError) {
    return res.status(error.statusCode || 500).json({
      error: error.message,
      code: error.code,
      provider: error.provider
    });
  }
  console.error('[Payment Error]:', error);
  res.status(500).json({ error: 'Internal server error processing payment' });
}
`;
}

export function generateEmailController(options = {}) {
  return `/**
 * Email Controller
 * Auto-generated by: npx mern-integrations init
 */

import { email } from '../config.js';
import { ValidationError, IntegrationError } from 'mern-integrations';

export async function sendEmail(req, res) {
  try {
    const { to, subject, html, text } = req.body;

    const result = await email.sendEmail({
      to,
      subject,
      html: html || \`<p>\${text || ''}</p>\`,
      text
    });

    res.status(200).json(result);
  } catch (error) {
    if (error instanceof ValidationError) {
      return res.status(400).json({ error: error.message, details: error.details });
    }
    if (error instanceof IntegrationError) {
      return res.status(error.statusCode || 500).json({
        error: error.message,
        code: error.code,
        provider: error.provider
      });
    }
    console.error('[Email Error]:', error);
    res.status(500).json({ error: 'Internal server error sending email' });
  }
}
`;
}

export function generateSMSController(options = {}) {
  return `/**
 * SMS & OTP Controller
 * Auto-generated by: npx mern-integrations init
 */

import { sms } from '../config.js';
import { ValidationError, IntegrationError } from 'mern-integrations';

export async function sendOtp(req, res) {
  try {
    const { to, otpLength = 6 } = req.body;

    if (!sms.capabilities.includes('sendOTP')) {
      return res.status(400).json({ error: 'OTP sending not supported by this SMS provider' });
    }

    const result = await sms.sendOTP({
      to,
      otpLength: Number(otpLength)
    });

    res.status(200).json(result);
  } catch (error) {
    handleError(res, error);
  }
}

export async function verifyOtp(req, res) {
  try {
    const { to, otp } = req.body;

    if (!sms.capabilities.includes('verifyOTP')) {
      return res.status(400).json({ error: 'OTP verification not supported by this SMS provider' });
    }

    const result = await sms.verifyOTP({ to, otp: String(otp) });
    res.status(200).json(result);
  } catch (error) {
    handleError(res, error);
  }
}

export async function sendMessage(req, res) {
  try {
    const { to, message } = req.body;

    const result = await sms.sendSMS({ to, message });
    res.status(200).json(result);
  } catch (error) {
    handleError(res, error);
  }
}

function handleError(res, error) {
  if (error instanceof ValidationError) {
    return res.status(400).json({ error: error.message, details: error.details });
  }
  if (error instanceof IntegrationError) {
    return res.status(error.statusCode || 500).json({
      error: error.message,
      code: error.code,
      provider: error.provider
    });
  }
  console.error('[SMS Error]:', error);
  res.status(500).json({ error: 'Internal server error processing SMS' });
}
`;
}

export function generateStorageController(options = {}) {
  return `/**
 * Storage Controller
 * Auto-generated by: npx mern-integrations init
 */

import { storage } from '../config.js';
import { ValidationError, IntegrationError } from 'mern-integrations';

export async function getUploadUrl(req, res) {
  try {
    const { key, publicId, signed = true, expiresIn = 1800 } = req.body;

    const result = await storage.getUrl({
      key: key || publicId,
      publicId: publicId || key,
      signed: Boolean(signed),
      expiresIn: Number(expiresIn)
    });

    res.status(200).json(result);
  } catch (error) {
    handleError(res, error);
  }
}

export async function deleteFile(req, res) {
  try {
    const { key, publicId } = req.body;

    const result = await storage.delete({
      key: key || publicId,
      publicId: publicId || key
    });

    res.status(200).json(result);
  } catch (error) {
    handleError(res, error);
  }
}

function handleError(res, error) {
  if (error instanceof ValidationError) {
    return res.status(400).json({ error: error.message, details: error.details });
  }
  if (error instanceof IntegrationError) {
    return res.status(error.statusCode || 500).json({
      error: error.message,
      code: error.code,
      provider: error.provider
    });
  }
  console.error('[Storage Error]:', error);
  res.status(500).json({ error: 'Internal server error processing storage operation' });
}
`;
}

